INSERT INTO password_reset_challenge (
    challenge_id, user_id, email_fingerprint, request_ip_fingerprint, code_hmac,
    created_at, expires_at
) VALUES (
    #{challengeId}, #{userId}, #{emailFingerprint}, #{requestIpFingerprint}, #{codeHmac},
    #{createdAt}, #{expiresAt}
)

mapper.update:
UPDATE password_reset_challenge
   SET verified_at = #{verifiedAt},
       grant_hmac = #{grantHmac},
       grant_expires_at = #{grantExpiresAt}
 WHERE challenge_id = #{challengeId}
   AND user_id IS NOT NULL
   AND consumed_at IS NULL
   AND verified_at IS NULL
   AND expires_at > #{verifiedAt}
   AND attempt_count < 5

UPDATE password_reset_challenge
   SET consumed_at = #{now}, grant_hmac = NULL, grant_expires_at = NULL
 WHERE challenge_id = #{challengeId}
   AND consumed_at IS NULL
   AND verified_at IS NOT NULL
   AND grant_hmac = #{grantHmac}
   AND grant_expires_at > #{now}

mapper.select:
SELECT bucket_type, bucket_fingerprint, window_started_at, request_count,
       failure_count, last_requested_at
  FROM password_reset_rate_limit
 WHERE bucket_type = #{bucketType}
   AND bucket_fingerprint = #{bucketFingerprint}
   FOR UPDATE

mapper.update:
UPDATE password_reset_rate_limit
   SET window_started_at = #{windowStartedAt},
       request_count = #{requestCount},
       failure_count = #{failureCount},
       last_requested_at = #{lastRequestedAt}
 WHERE bucket_type = #{bucketType}
   AND bucket_fingerprint = #{bucketFingerprint}

mapper.delete:
DELETE FROM password_reset_rate_limit
 WHERE window_started_at < #{cutoff}
 LIMIT 100
